21	STATIC hdcError_t drv_hdc_client_create_para_checker(const HDC_CLIENT *pClient, signed int maxSessionNum,
22	                                                     signed int serviceType, signed int flag)
23	{
24	    signed int max_session_num_by_type;
25	
26	    if (pClient == NULL) {
27	        HDC_LOG_ERR("Input parameter pClient is NULL.\n");
28	        return DRV_ERROR_INVALID_VALUE;
29	    }
30	
31	    max_session_num_by_type = drv_hdc_get_max_session_num_by_type(serviceType);
32	    if ((maxSessionNum <= 0) || (maxSessionNum > max_session_num_by_type)) {
33	        HDC_LOG_ERR("Input parameter maxSessionNum is error. (maxSessionNum=%d)\n", maxSessionNum);
34	        return DRV_ERROR_INVALID_VALUE;
35	    }
36	
37	    if ((serviceType >= HDC_SERVICE_TYPE_MAX) || (serviceType < 0)) {
38	        HDC_LOG_ERR("Input parameter serviceType is error. (serviceType=%d)\n", serviceType);
39	        return DRV_ERROR_INVALID_VALUE;
40	    }
41	
42	    if ((flag < 0) || (flag > HDC_SESSION_CONN_TIMEOUT)) {
43	        HDC_LOG_ERR("Input parameter flag is error. (flag=%d).\n", flag);
44	        return DRV_ERROR_INVALID_VALUE;
45	    }
46	
47	    return DRV_ERROR_NONE;
48	}
