50	/*****************************************************************************
51	 * Function Name        : drvHdcClientCreate
52	 * Function Description : Create an HDC client and initialize it based on the maximum number of sessions and
53	 *                        service type
54	 * Input Parameters     : int maxSessionNum  The maximum number of sessions currently required by Client
55	 *                        int serviceType  select service type
56	 *                        int flag         Reserved parameters, [bit0 - bit7] session connect timeout, other fixed to 0
57	 * Output Parameters    : HDC_CLIENT *client  Created HDC Client pointer
58	 * Return Value         : DRV_ERROR_NONE
59	 *                        DRV_ERROR_INVALID_VALUE
60	 * Caller Function      :
61	 * Called Function      :
62	 *
63	 * Modification History :
64	 * 1.Date               : January 15, 2018
65	 *  Modification        : New generated function
66	 *
67	 *****************************************************************************/
68	hdcError_t drvHdcClientCreate(HDC_CLIENT *client, signed int maxSessionNum, signed int serviceType, signed int flag)
69	{
70	    struct hdc_client_session *pSession = NULL;
71	    struct hdc_client_head *pHead = NULL;
72	    size_t size;
73	    signed int cnt;
74	
75	    /* sanity check */
76	    if (drv_hdc_client_create_para_checker(client, maxSessionNum, serviceType, flag) != DRV_ERROR_NONE) {
77	        return DRV_ERROR_INVALID_VALUE;
78	    }
79	
80	    size = sizeof(struct hdc_client_session) * (size_t)maxSessionNum + sizeof(struct hdc_client_head);
81	
82	    /* malloc memory for client */
83	    pHead = (struct hdc_client_head *)drv_hdc_zalloc(size);
84	    if (pHead == NULL) {
85	        HDC_LOG_ERR("Call malloc failed.\n");
86	        hdc_report_out_of_mem_err_msg(size);
87	        return DRV_ERROR_OUT_OF_MEMORY;
88	    }
89	
90	    /* initialization */
91	    pHead->serviceType = serviceType;
92	    pHead->magic = HDC_MAGIC_WORD;
93	    pHead->flag = (unsigned int)((flag == 0) ? HDC_SESSION_CONN_TIMEOUT : flag);
94	    pHead->maxSessionNum = (unsigned int)maxSessionNum;
95	    (void)mmMutexInit(&pHead->mutex);
96	
97	    pSession = pHead->session;
98	
99	    for (cnt = 0; cnt < maxSessionNum; cnt++) {
100	        pSession[cnt].session.magic = HDC_MAGIC_WORD;
101	        pSession[cnt].session.sockfd = -1;
102	        pSession[cnt].session.bind_fd = HDC_SESSION_FD_INVALID;
103	        pSession[cnt].alloc = false;
104	        pSession[cnt].node = -1;
105	        pSession[cnt].devid = -1;
106	    }
107	
108	    *client = (HDC_CLIENT)pHead;
109	
110	    HDC_LOG_DEBUG("Create client success.\n");
111	
112	    return DRV_ERROR_NONE;
113	}
