115	/*****************************************************************************
116	 * Function Name         : drvHdcClientDestroy
117	 * Function Description  : Release HDC Client
118	 * Input Parameters      : HDC_CLIENT client  HDC Client to be released
119	 * Output Parameters     : None
120	 * Return Value          : DRV_ERROR_NONE
121	 *                        DRV_ERROR_INVALID_VALUE
122	 *                        DRV_ERROR_CLIENT_BUSY
123	 * Caller Function       :
124	 * Called Function       :
125	 *
126	 * Modification History  :
127	 * 1.Date                : January 15, 2018
128	 *  Modification         : New generated function
129	 *
130	 *****************************************************************************/
131	hdcError_t drvHdcClientDestroy(HDC_CLIENT client)
132	{
133	    struct hdc_client_session *pSession = NULL;
134	    struct hdc_client_head *pHead = NULL;
135	    bool alive = false;
136	    unsigned int maxSessionNum;
137	    unsigned int cnt;
138	    signed int ret;
139	
140	    if (client == NULL) {
141	        HDC_LOG_ERR("Input parameter client is NULL.\n");
142	        return DRV_ERROR_INVALID_VALUE;
143	    }
144	
145	    pHead = (struct hdc_client_head *)client;
146	
147	    if (pHead->magic != HDC_MAGIC_WORD) {
148	        HDC_LOG_ERR("Variable pHead_magic is invalid. (pHead_magic=%#x)\n", pHead->magic);
149	        return DRV_ERROR_INVALID_VALUE;
150	    }
151	
152	    if ((pHead->maxSessionNum <= 0) || (pHead->maxSessionNum > HDCDRV_SUPPORT_MAX_SESSION)) {
153	        HDC_LOG_ERR("Input parameter maxSessionNum is error. (maxSessionNum=%u)\n", pHead->maxSessionNum);
154	        return DRV_ERROR_INVALID_VALUE;
155	    }
156	
157	    maxSessionNum = pHead->maxSessionNum;
158	    pSession = pHead->session;
159	
160	    (void)mmMutexLock(&pHead->mutex);
161	
162	    for (cnt = 0; cnt < maxSessionNum; cnt++) {
163	        if (pSession[cnt].session.sockfd != -1) {
164	            alive = true;
165	            HDC_LOG_WARN("Session still alive. (session=%u)\n", pSession[cnt].session.sockfd);
166	        }
167	    }
168	    if (alive) {
169	        (void)mmMutexUnLock(&pHead->mutex);
170	        HDC_LOG_WARN("Must close session before destroy client, serviceType %d.\n", pHead->serviceType);
171	        return DRV_ERROR_CLIENT_BUSY;
172	    }
173	
174	    (void)mmMutexUnLock(&pHead->mutex);
175	
176	    if (g_hdcConfig.trans_type == HDC_TRANS_USE_PCIE) {
177	        if ((ret = hdc_pcie_client_destroy(g_hdcConfig.pcie_handle, 0, pHead->serviceType)) != 0) {
178	            HDC_LOG_WARN("Destroy pcie client not success. (errno=%d)\n", ret);
179	        }
180	    }
181	    (void)mmMutexDestroy(&pHead->mutex);
182	    pHead->magic = 0;
183	    free(client);
184	    pHead = NULL;
185	
186	    HDC_LOG_DEBUG("Destroy client.\n");
187	    return DRV_ERROR_NONE;
188	}
