190	/*****************************************************************************
191	 * Function Name         : drv_hdc_client_alloc_session
192	 * Function Description  : Find an available Session
193	 * Input Parameters      : struct hdc_client_head
194	 * Output Parameters     : struct hdc_client_session **ppSession
195	 * Return Value          :
196	 * Caller Function       :
197	 * Called Function       :
198	 *
199	 * Modification History  :
200	 * 1.Date                : January 16, 2018
201	 *  Modification         : New generated function
202	 *
203	 *****************************************************************************/
204	STATIC bool drv_hdc_client_alloc_session(struct hdc_client_head *pHead, struct hdc_client_session **ppSession)
205	{
206	    struct hdc_client_session *pSession = NULL;
207	    unsigned int maxSessionNum;
208	    unsigned int cnt;
209	
210	    maxSessionNum = (unsigned int)drv_hdc_get_max_session_num_by_type(pHead->serviceType);
211	    if ((pHead->maxSessionNum <= 0) || (pHead->maxSessionNum > maxSessionNum)) {
212	        HDC_LOG_ERR("Input parameter maxSessionNum is error. (maxSessionNum=%u)\n", pHead->maxSessionNum);
213	        return false;
214	    }
215	
216	    (void)mmMutexLock(&pHead->mutex);
217	
218	    pSession = pHead->session;
219	    maxSessionNum = pHead->maxSessionNum;
220	    for (cnt = 0; cnt < maxSessionNum; cnt++) {
221	        if (!(pSession[cnt].alloc)) {
222	            pSession[cnt].alloc = true;
223	            pSession[cnt].session.sockfd = -1;
224	            pSession[cnt].session.bind_fd = HDC_SESSION_FD_INVALID;
225	#ifdef CFG_FEATURE_SUPPORT_UB
226	            pSession[cnt].session.close_eventfd = -1;
227	            pSession[cnt].session.epoll_head = NULL;
228	#endif
229	            break;
230	        }
231	    }
232	    if (cnt == maxSessionNum) {
233	        (void)mmMutexUnLock(&pHead->mutex);
234	        HDC_LOG_ERR("No free session.\n");
235	        return false;
236	    }
237	
238	    *ppSession = &pSession[cnt];
239	
240	    (void)mmMutexUnLock(&pHead->mutex);
241	
242	    HDC_LOG_DEBUG("Client alloc session success.\n");
243	    return true;
244	}
245	
246	/*****************************************************************************
247	 * Function Name         : drv_hdc_client_free_session
248	 * Function Description  : Release Client-side Session
249	 * Input Parameters      : struct hdc_client_session *pSession
250	 * Output Parameters     : None
251	 * Return Value          :
252	 * Caller Function       :
253	 * Called Function       :
254	 *
255	 * Modification History  :
256	 * 1.Date                : January 17, 2018
257	 *  Modification         : New generated function
258	 *****************************************************************************/
259	STATIC void drv_hdc_client_free_session(struct hdc_client_head *pHead, struct hdc_client_session *pSession)
260	{
261	    (void)mmMutexLock(&pHead->mutex);
262	    pSession->alloc = false;
263	    pSession->session.sockfd = -1;
264	    (void)mmMutexUnLock(&pHead->mutex);
265	
266	    HDC_LOG_DEBUG("Client free session.\n");
267	    return;
268	}
