270	STATIC hdcError_t drv_hdc_connect_para_check(signed int peer_node, signed int peer_devid,
271	                                             const struct hdc_client_head *pHead, const HDC_SESSION *pSession)
272	{
273	    if (peer_node != 0) {
274	        HDC_LOG_ERR("Input parameter peer_node is error.\n");
275	        return DRV_ERROR_INVALID_VALUE;
276	    }
277	    if (pHead == NULL) {
278	        HDC_LOG_ERR("Input parameter pHead is NULL.\n");
279	        return DRV_ERROR_INVALID_VALUE;
280	    }
281	    if (pSession == NULL) {
282	        HDC_LOG_ERR("Input parameter pSession is NULL.\n");
283	        return DRV_ERROR_INVALID_VALUE;
284	    }
285	    if ((peer_devid >= hdc_get_max_device_num()) || (peer_devid < 0)) {
286	        HDC_LOG_ERR("Input parameter peer_devid is error. (dev_id=%d)\n", peer_devid);
287	        return DRV_ERROR_INVALID_DEVICE;
288	    }
289	    if (pHead->magic != HDC_MAGIC_WORD) {
290	        HDC_LOG_ERR("Input parameter magic is error. (pHead_magic=%#x)\n", pHead->magic);
291	        return DRV_ERROR_INVALID_VALUE;
292	    }
293	
294	    return DRV_ERROR_NONE;
295	}
