298	hdcError_t halHdcSessionConnectEx(int peer_node, int peer_devid, int peer_pid, HDC_CLIENT client, HDC_SESSION *pSession)
299	{
300	    struct hdc_client_head *pHead = (struct hdc_client_head *)client;
301	    struct hdc_client_session *p_client_session_ppc = NULL;
302	    struct hdc_client_session *p_client_session = NULL;
303	    bool result = false;
304	    hdcError_t err_code;
305	    signed int ret;
306	
307	    err_code = drv_hdc_connect_para_check(peer_node, peer_devid, pHead, pSession);
308	    if (err_code != DRV_ERROR_NONE) {
309	        return err_code;
310	    }
311	
312	    result = drv_hdc_client_alloc_session(pHead, &p_client_session);
313	    if ((!result) || (p_client_session == NULL)) {
314	        HDC_LOG_ERR("No available session.\n");
315	        return DRV_ERROR_OVER_LIMIT;
316	    }
317	
318	    if (g_hdcConfig.trans_type == HDC_TRANS_USE_PCIE) {
319	        if (g_hdcConfig.h2d_type == HDC_TRANS_USE_UB) {
320	            ret = hdc_ub_connect(peer_devid, pHead, peer_pid, &p_client_session->session);
321	        } else if (g_hdcConfig.h2d_type == HDC_TRANS_USE_PCIE) {
322	            ret = hdc_pcie_connect(g_hdcConfig.pcie_handle, peer_devid, pHead->serviceType, pHead->flag, peer_pid,
323	                                   &p_client_session->session);
324	        } else {
325	            HDC_LOG_ERR("Variable h2d_type is invalid. (h2d_type=%#x)\n", g_hdcConfig.h2d_type);
326	            ret = DRV_ERROR_INVALID_HANDLE;
327	        }
328	        if (ret != 0) {
329	            drv_hdc_client_free_session(pHead, p_client_session);
330	            if (ret == -HDCDRV_PEER_REBOOT) {
331	                return DRV_ERROR_DEV_PROCESS_HANG;
332	            }
333	            if (ret == (-HDCDRV_REMOTE_SERVICE_NO_LISTENING)) {
334	                return DRV_ERROR_REMOTE_NOT_LISTEN;
335	            }
336	            if (ret == (-HDCDRV_NO_SESSION)) {
337	                return DRV_ERROR_REMOTE_NO_SESSION;
338	            }
339	            if (ret == (-HDCDRV_DEVICE_NOT_READY)) {
340	                return DRV_ERROR_DEVICE_NOT_READY;
341	            }
342	            if (ret == (-HDCDRV_SESSION_CHAN_INVALID)) {
343	                return DRV_ERROR_SOCKET_CONNECT;
344	            }
345	            if (ret == (-HDCDRV_CONNECT_TIMEOUT)) {
346	                return DRV_ERROR_WAIT_TIMEOUT;
347	            }
348	            if (ret == (-HDCDRV_SESSION_HAS_CLOSED)) {
349	                return DRV_ERROR_SOCKET_CLOSE;
350	            }
351	            if (ret == (-HDCDRV_SEND_CTRL_MSG_FAIL)) {
352	                return DRV_ERROR_NO_DEVICE;
353	            }
354	            return (hdcError_t)ret;
355	        }
356	    } else {
357	        err_code = drv_hdc_socket_session_connect(peer_devid, pHead->serviceType,
358	                                                  (HDC_SESSION *)(&p_client_session_ppc));
359	        if (err_code != DRV_ERROR_NONE) {
360	            drv_hdc_client_free_session(pHead, p_client_session);
361	            HDC_LOG_WARN("PPC client session connect not success. (err_code=%d)\n", (signed int)err_code);
362	            return DRV_ERROR_SOCKET_CONNECT;
363	        }
364	
365	        /* copy session magic/sockfd to session of alloc, and free ppc. */
366	        p_client_session->session.magic = p_client_session_ppc->session.magic;
367	        p_client_session->session.sockfd = p_client_session_ppc->session.sockfd;
368	        free(p_client_session_ppc);
369	        p_client_session_ppc = NULL;
370	    }
371	
372	    p_client_session->session.type = HDC_SESSION_CLINET;
373	    p_client_session->node = peer_node;
374	    p_client_session->devid = peer_devid;
375	    p_client_session->client = pHead;
376	    *pSession = (HDC_SESSION)p_client_session;
377	    return DRV_ERROR_NONE;
378	}
