403	/*****************************************************************************
404	 * Function Name         : drv_hdc_client_session_close
405	 * Function Description  : Release HDC Session
406	 * Input Parameters      : HDC_SESSION session    The session to be released
407	 * Output Parameters     : None
408	 * Return Value          : DRV_ERROR_NONE
409	 *                        DRV_ERROR_INVALID_VALUE
410	 * Caller Function       :
411	 * Called Function       :
412	 *
413	 * Modification History  :
414	 * 1.Date                : January 15, 2018
415	 *  Modification         : New generated function
416	 *
417	 *****************************************************************************/
418	hdcError_t drv_hdc_client_session_close(HDC_SESSION session, int close_state, int flag)
419	{
420	    struct hdc_client_session *p_client_session = NULL;
421	    struct hdc_client_head *pHead = NULL;
422	    signed int ret;
423	
424	    p_client_session = (struct hdc_client_session *)session;
425	
426	    if (!(p_client_session->alloc)) {
427	        HDC_LOG_ERR("Parameter alloc is error. (alloc=%d)\n", (signed int)p_client_session->alloc);
428	        return DRV_ERROR_INVALID_VALUE;
429	    }
430	
431	    if (p_client_session->client == NULL) {
432	        HDC_LOG_ERR("Parameter client is NULL.\n");
433	        return DRV_ERROR_INVALID_VALUE;
434	    }
435	
436	    HDC_LOG_INFO("Destroy client session. (sock=%d)\n", p_client_session->session.sockfd);
437	
438	    if (g_hdcConfig.trans_type == HDC_TRANS_USE_PCIE) {
439	        if (g_hdcConfig.h2d_type == HDC_TRANS_USE_UB) {
440	            ret = hdc_ub_session_close((unsigned int)p_client_session->devid, &p_client_session->session, close_state,
441	                                       flag);
442	        } else if (g_hdcConfig.h2d_type == HDC_TRANS_USE_PCIE) {
443	            ret = hdc_pcie_close(g_hdcConfig.pcie_handle, (unsigned int)p_client_session->devid,
444	                                 &p_client_session->session);
445	        } else {
446	            HDC_LOG_ERR("Variable h2d_type is invalid. (h2d_type=%#x)\n", g_hdcConfig.h2d_type);
447	            ret = DRV_ERROR_INVALID_HANDLE;
448	        }
449	        if (ret != 0) {
450	            HDC_LOG_WARN("Close device not success. (device=%d; errno=%d)\n", (signed int)(p_client_session->devid),
451	                         ret);
452	        }
453	
454	        if (g_hdcConfig.h2d_type == HDC_TRANS_USE_UB) {
455	            hdc_link_event_pre_uninit(p_client_session->devid);
456	        }
457	
