462	        (void)mm_close_socket(p_client_session->session.sockfd);
463	    }
464	
465	    pHead = p_client_session->client;
466	    drv_hdc_client_free_session(pHead, p_client_session);
467	
468	    return DRV_ERROR_NONE;
