20	STATIC void drv_hdc_preset_session_init(struct hdc_server_head *pHead, int session_num)
21	{
22	#ifdef CFG_FEATURE_PRESET_SESSION
23	    int i;
24	    for (i = 0; i < session_num; ++i) {
25	        pHead->session[i].alloc = false;
26	        pHead->session[i].session.magic = HDC_MAGIC_WORD;
27	        pHead->session[i].session.sockfd = -1;
28	        pHead->session[i].session.bind_fd = HDC_SESSION_FD_INVALID;
