36	STATIC hdcError_t drv_hdc_pcie_server_create(signed int devid, signed int serviceType, HDC_SERVER *pServer)
37	{
38	    struct hdc_server_head *pHead = NULL;
39	    mmProcess fd;
40	    signed int ret;
41	    size_t session_size = 0, size;
42	    int session_num = drv_hdc_get_max_session_num_by_type(serviceType);
43	
44	#ifdef CFG_FEATURE_PRESET_SESSION
45	    session_size = (size_t)session_num * sizeof(struct hdc_server_session);
46	#endif
47	    size = sizeof(struct hdc_server_head) + session_size;
48	    pHead = malloc(size);
49	    if (pHead == NULL) {
50	        HDC_LOG_ERR("Call malloc failed.\n");
51	        hdc_report_out_of_mem_err_msg(size);
52	        return DRV_ERROR_OUT_OF_MEMORY;
53	    }
54	
55	    pHead->serviceType = serviceType;
56	
57	    if (g_hdcConfig.h2d_type == HDC_TRANS_USE_PCIE) {
58	        ret = hdc_pcie_set_service_level(g_hdcConfig.pcie_handle, serviceType);
59	        if (ret != DRV_ERROR_NONE) {
60	            free(pHead);
61	            pHead = NULL;
62	            HDC_LOG_ERR("HDC init, set service level failed. (errno=%d)\n", ret);
63	            if (ret == (-HDCDRV_DEVICE_NOT_READY)) {
64	                /* 17 mean HDCDRV_DEVICE_NOT_READY in kernel */
65	                return DRV_ERROR_DEVICE_NOT_READY;
66	            }
67	            return DRV_ERROR_IOCRL_FAIL;
68	        }
69	    }
70	
71	    fd = hdc_pcie_create_bind_fd();
72	    if (fd == (mmProcess)EN_ERROR) {
73	        free(pHead);
74	        pHead = NULL;
75	        HDC_LOG_ERR("Server create open pcie device failed. (strerror=\"%s\")\n", strerror(errno));
76	        return DRV_ERROR_INVALID_HANDLE;
77	    }
78	
79	    if (g_hdcConfig.h2d_type == HDC_TRANS_USE_UB) {
80	        ret = hdc_ub_server_create(fd, devid, serviceType, pHead);
81	    } else if (g_hdcConfig.h2d_type == HDC_TRANS_USE_PCIE) {
82	        ret = hdc_pcie_server_create(fd, devid, serviceType);
83	    } else {
84	        HDC_LOG_ERR("Variable h2d_type is invalid. (h2d_type=%#x)\n", g_hdcConfig.h2d_type);
85	        ret = DRV_ERROR_INVALID_HANDLE;
86	    }
87	    if (ret != DRV_ERROR_NONE) {
88	        free(pHead);
89	        pHead = NULL;
90	        hdc_pcie_close_bind_fd(fd);
91	        fd = HDC_SESSION_FD_INVALID;
92	
93	        /* 17 mean HDCDRV_DEVICE_NOT_READY in kernel */
94	        if (ret == (-HDCDRV_DEVICE_NOT_READY)) {
95	            return DRV_ERROR_DEVICE_NOT_READY;
96	        } else if (ret == (-HDCDRV_SERVICE_LISTENING)) {
97	            HDC_LOG_WARN("Server has already been created. (listen_device=%d, serviceType=%d) \n", devid, serviceType);
98	            return DRV_ERROR_SERVER_HAS_BEEN_CREATED;
99	        } else {
100	            HDC_LOG_ERR("Create server failed. (listen_device=%d; ret=%d) \n", devid, ret);
101	            return DRV_ERROR_SERVER_CREATE_FAIL;
102	        }
103	    }
104	
105	    pHead->bind_fd = fd;
106	    pHead->listenFd = devid;
107	    drv_hdc_preset_session_init(pHead, session_num);
108	    *pServer = (HDC_SERVER)pHead;
109	    return DRV_ERROR_NONE;
110	}
111	
112	#ifdef CFG_FEATURE_PRESET_SESSION
113	STATIC void drv_hdc_server_alloc_session(struct hdc_server_head *pServ, struct hdc_server_session **pp_serv_session)
114	{
115	    int session_num = drv_hdc_get_max_session_num_by_type(pServ->serviceType);
116	    struct hdc_server_session *pSession = NULL;
117	    int i = 0;
118	
119	    *pp_serv_session = NULL;
120	    (void)mmMutexLock(&pServ->mutex);
121	    pSession = pServ->session;
122	    for (i = 0; i < session_num; ++i) {
123	        if (!pSession[i].alloc) {
124	            pSession[i].alloc = true;
125	            break;
126	        }
127	    }
128	
129	    (void)mmMutexUnLock(&pServ->mutex);
130	    if (i == session_num) {
131	        HDC_LOG_ERR("no free server session.\n");
132	        return;
133	    }
134	
135	    *pp_serv_session = &pSession[i];
136	    return;
137	}
138	
139	STATIC void drv_hdc_server_free_session(struct hdc_server_head *pServ, struct hdc_server_session *p_serv_session)
140	{
141	    (void)mmMutexLock(&pServ->mutex);
142	    p_serv_session->alloc = false;
143	    p_serv_session->session.sockfd = -1;
144	    (void)mmMutexUnLock(&pServ->mutex);
145	}
146	#endif
