148	STATIC hdcError_t drv_hdc_pcie_session_accept(HDC_SERVER server, HDC_SESSION *pSession)
149	{
150	    struct hdc_server_head *pServ = NULL;
151	    struct hdc_server_session *p_serv_session = NULL;
152	    signed int ret, deviceId, serviceType;
153	    struct hdc_session *session = NULL;
154	
155	    pServ = (struct hdc_server_head *)server;
156	    deviceId = pServ->deviceId;
157	    serviceType = pServ->serviceType;
158	#ifdef CFG_FEATURE_PRESET_SESSION
159	    drv_hdc_server_alloc_session(pServ, &p_serv_session);
160	#else
161	    p_serv_session = (struct hdc_server_session *)drv_hdc_zalloc(sizeof(struct hdc_server_session));
162	#endif
163	    if (p_serv_session == NULL) {
164	        HDC_LOG_ERR("Call malloc failed.\n");
165	        hdc_report_out_of_mem_err_msg(sizeof(struct hdc_server_session));
166	        return DRV_ERROR_OUT_OF_MEMORY;
167	    }
168	
169	    session = &p_serv_session->session;
170	    session->bind_fd = HDC_SESSION_FD_INVALID;
171	
172	    if (g_hdcConfig.h2d_type == HDC_TRANS_USE_UB) {
173	        ret = hdc_ub_accept(pServ, deviceId, serviceType, &p_serv_session->session);
174	    } else if (g_hdcConfig.h2d_type == HDC_TRANS_USE_PCIE) {
175	        ret = hdc_pcie_accept(g_hdcConfig.pcie_handle, deviceId, serviceType, &p_serv_session->session);
176	    } else {
177	        HDC_LOG_ERR("Variable h2d_type is invalid. (h2d_type=%#x)\n", g_hdcConfig.h2d_type);
178	        ret = DRV_ERROR_INVALID_HANDLE;
179	    }
180	    if (ret != DRV_ERROR_NONE) {
181	#ifdef CFG_FEATURE_PRESET_SESSION
182	        drv_hdc_server_free_session(pServ, p_serv_session);
183	#else
184	        free(p_serv_session);
185	        p_serv_session = NULL;
186	#endif
187	        if (ret == -HDCDRV_PEER_REBOOT) {
188	            HDC_LOG_INFO("peer reset. (dev_id=%d; server=%d; ret=%d)\n", pServ->deviceId, pServ->serviceType, ret);
189	            return DRV_ERROR_DEV_PROCESS_HANG;
190	        }
191	
192	        if (ret == -HDCDRV_DEVICE_RESET) {
193	            HDC_LOG_INFO("Server is destroyed or wakeup wait. (dev_id=%d; server=%d; ret=%d)\n", pServ->deviceId,
194	                         pServ->serviceType, ret);
195	            return DRV_ERROR_DEVICE_NOT_READY;
196	        }
197	
198	        if (ret == -HDCDRV_DEVICE_NOT_READY) {
199	            HDC_LOG_RUN_INFO_LIMIT("Dev not ready or has been freed. (dev_id=%d; server=%d; ret=%d)\n", pServ->deviceId,
200	                                   pServ->serviceType, ret);
201	        } else {
202	            HDC_LOG_ERR("Accept failed. (dev_id=%d; server=%d; ret=%d)\n", pServ->deviceId, pServ->serviceType, ret);
203	        }
204	
205	        return DRV_ERROR_SOCKET_ACCEPT;
206	    }
207	
208	    *pSession = p_serv_session;
209	    return DRV_ERROR_NONE;
210	}
