285	/*****************************************************************************
286	 * Function Name         : drvHdcServerDestroy
287	 * Function Description  : Release HDC Server
288	 * Input Parameters      : HDC_SERVER server  HDC server to be released
289	 * Output Parameters     : None
290	 * Return Value          : DRV_ERROR_NONE
291	 *                        DRV_ERROR_INVALID_VALUE
292	 * Caller Function       :
293	 * Called Function       :
294	 *
295	 * Modification History  :
296	 * 1.Date                : January 15, 2018
297	 *  Modification         : New generated function
298	 *
299	 *****************************************************************************/
300	hdcError_t drvHdcServerDestroy(HDC_SERVER server)
301	{
302	    signed int ret;
303	    struct hdc_server_head *pServ = NULL;
304	    unsigned int session_num;
305	    mmSockHandle listenFd;
306	    int retry_time = 0;
307	
308	    if (server == NULL) {
309	        HDC_LOG_ERR("Input parameter server is NULL.\n");
310	        return DRV_ERROR_INVALID_VALUE;
311	    }
312	
313	    pServ = (struct hdc_server_head *)server;
314	    if ((pServ->deviceId >= hdc_get_max_device_num()) || (pServ->deviceId < 0)) {
315	        HDC_LOG_ERR("Input parameter deviceId is error. (deviceId=%d)\n", pServ->deviceId);
316	        return DRV_ERROR_INVALID_DEVICE;
317	    }
318	
319	    if (pServ->magic != HDC_MAGIC_WORD) {
320	        HDC_LOG_ERR("Input parameter magic is error. (magic=%#x)\n", pServ->magic);
321	        return DRV_ERROR_INVALID_VALUE;
322	    }
323	
324	    (void)mmMutexLock(&pServ->mutex);
325	    session_num = pServ->session_num;
326	    if (session_num > 0) {
327	        (void)mmMutexUnLock(&pServ->mutex);
328	        HDC_LOG_WARN("Destroy server not success, there have session alive. (session_num=%d)\n", session_num);
329	        return DRV_ERROR_SERVER_BUSY;
330	    }
331	    (void)mmMutexUnLock(&pServ->mutex);
332	
333	    if (g_hdcConfig.trans_type == HDC_TRANS_USE_PCIE) {
334	        if (g_hdcConfig.h2d_type == HDC_TRANS_USE_UB) {
335	            ret = hdc_ub_server_destroy(pServ, pServ->deviceId, pServ->serviceType);
336	        } else if (g_hdcConfig.h2d_type == HDC_TRANS_USE_PCIE) {
337	            ret = hdc_pcie_server_destroy(pServ->bind_fd, pServ->deviceId, pServ->serviceType);
338	        } else {
339	            HDC_LOG_ERR("Variable h2d_type is invalid. (h2d_type=%#x)\n", g_hdcConfig.h2d_type);
340	            ret = DRV_ERROR_INVALID_HANDLE;
341	        }
342	        if (ret != 0) {
343	            HDC_LOG_WARN("Destroy pcie server not success. (dev_id=%d; errno=%d)\n", pServ->deviceId, ret);
344	        }
345	
346	        if (g_hdcConfig.h2d_type == HDC_TRANS_USE_UB) {
347	            hdc_link_event_pre_uninit(pServ->deviceId);
348	        }
349	
350	        hdc_pcie_close_bind_fd(pServ->bind_fd);
351	        pServ->bind_fd = HDC_SESSION_FD_INVALID;
352	    } else {
353	        listenFd = pServ->listenFd;
354	        pServ->listenFd = -1;
355	        wmb();
356	        (void)shutdown(listenFd, SHUT_RDWR);
357	        (void)mm_close_socket(listenFd);
358	        while ((pServ->accept_wait == HDC_ACCEPT_WAITING) && (retry_time < HDC_SOCKET_MAX_RETRY_TIMES)) {
359	            usleep(HDC_SERVER_DESTORY_WAIT_TIME_US);
360	            retry_time++;
361	        }
362	        if (retry_time == HDC_SOCKET_MAX_RETRY_TIMES) {
363	            HDC_LOG_ERR("Accept exit timeout. listenFd = %d\n", listenFd);
364	        }
365	    }
366	
367	    HDC_LOG_INFO("Destroy server success. (deviceId=%d; service_Type=%d)\n", pServ->deviceId, pServ->serviceType);
368	    (void)mmMutexDestroy(&pServ->mutex);
369	    pServ->magic = 0;
370	    free(pServ);
371	    pServ = NULL;
372	
373	    return DRV_ERROR_NONE;
374	}
