512	            ret = DRV_ERROR_INVALID_HANDLE;
513	        }
514	        if (ret != 0) {
515	            HDC_LOG_WARN("Close pcie session not success. (device=%d; sessiondID=%d; errno=%d)\n",
516	                         p_serv_session->deviceId, p_serv_session->session.sockfd, ret);
517	        }
518	
519	        if (g_hdcConfig.h2d_type != HDC_TRANS_USE_UB) {
520	            hdc_pcie_close_bind_fd(p_serv_session->session.bind_fd);
521	            p_serv_session->session.bind_fd = HDC_SESSION_FD_INVALID;
522	        }
523	    } else {
524	        (void)shutdown(p_serv_session->session.sockfd, SHUT_RDWR);
525	        (void)mm_close_socket(p_serv_session->session.sockfd);
526	    }
527	
528	    pServ = p_serv_session->server;
529	
530	    (void)mmMutexLock(&pServ->mutex);
531	    pServ->session_num--;
532	    (void)mmMutexUnLock(&pServ->mutex);
533	
534	#ifdef CFG_FEATURE_PRESET_SESSION
535	    if (g_hdcConfig.trans_type == HDC_TRANS_USE_PCIE) {
536	        drv_hdc_server_free_session(pServ, p_serv_session);
537	        return DRV_ERROR_NONE;
538	    }
539	#endif
540	    p_serv_session->session.magic = 0;
541	    free(p_serv_session);
542	    p_serv_session = NULL;
543	    return DRV_ERROR_NONE;
544	}
