359	STATIC signed int drv_hdc_get_page_size(mmProcess handle)
360	{
361	    unsigned int hdc_huge_page_size = 0;
362	    unsigned int hdc_page_size_bit = 0;
363	    unsigned int hdc_page_size = 0;
364	    signed int ret;
365	
366	    if (handle == (mmProcess)EN_ERROR) {
367	        HDC_LOG_ERR("Input parameter is error.\n");
368	        return DRV_ERROR_INVALID_HANDLE;
369	    }
370	
371	    ret = hdc_pcie_get_page_size(handle, &hdc_page_size, &hdc_huge_page_size, &hdc_page_size_bit);
372	    if (ret != DRV_ERROR_NONE) {
373	        HDC_LOG_ERR("Get page size failed. (ret=%d; STRERROR=\"%s\")\n", ret, STRERROR(ret));
374	        return DRV_ERROR_IOCRL_FAIL;
375	    }
376	    g_hdcPageSize = hdc_page_size;
377	    g_hdcHugePageSize = hdc_huge_page_size;
378	    g_hdcPageSizeBit = hdc_page_size_bit;
379	    g_hdcPageMask = (~(g_hdcPageSize - 1));
380	    g_hdcHugePageMask = (~(g_hdcHugePageSize - 1));
381	
382	    return DRV_ERROR_NONE;
383	}
