401	void *drv_hdc_zalloc(size_t size)
402	{
403	    void *pBuf = NULL;
404	
405	    if (size == 0) {
406	        HDC_LOG_ERR("Input parameter is error. (size=%lu)\n", (unsigned long)size);
407	        return NULL;
408	    }
409	
410	    pBuf = malloc(size);
411	    if (pBuf == NULL) {
412	        HDC_LOG_ERR("Call malloc failed. (size=%lu)\n", (unsigned long)size);
413	        return NULL;
414	    }
415	
416	    if (memset_s(pBuf, size, 0, size) != 0) {
417	        free(pBuf);
418	        pBuf = NULL;
419	        HDC_LOG_ERR("Call memset_s failed. (strerror=\"%s\")\n", strerror(errno));
420	        return NULL;
421	    }
422	
423	    return pBuf;
424	}
