426	STATIC hdcError_t hdc_phandle_get(struct hdcConfig *hdcConfig)
427	{
428	    hdcError_t ret = DRV_ERROR_NONE;
429	    signed int i = hdc_get_handle_count();
430	
431	    /* Waiting for permission to open /dev/hisi_dev */
432	    HDC_LOG_INFO("HDC trans_type=%d, h2d_type=%#x.\n", hdcConfig->trans_type, hdcConfig->h2d_type);
433	    while (i--) {
434	        if (hdcConfig->h2d_type == HDC_TRANS_USE_UB) {
435	            hdcConfig->pcie_handle = hdc_ub_open();
436	            HDC_LOG_INFO("Open ub.\n");
437	        } else if (hdcConfig->h2d_type == HDC_TRANS_USE_PCIE) {
438	            hdcConfig->pcie_handle = hdc_pcie_open();
439	            HDC_LOG_INFO("Open pcie.\n");
440	        } else {
441	            HDC_LOG_ERR("Variable h2d_type is invalid. (h2d_type=%#x)\n", g_hdcConfig.h2d_type);
442	            hdcConfig->pcie_handle = EN_ERROR;
443	            break;
444	        }
445	        if (hdcConfig->pcie_handle != (mmProcess)EN_ERROR) {
446	            break;
