330	signed int hdc_pcie_send(mmProcess handle, const struct hdc_session *pSession, struct drvHdcMsg *pMsg, signed int wait,
331	                         unsigned int timeout)
332	{
333	    signed int ret;
334	    union hdcdrv_cmd hdcCmd;
335	    struct timespec now_time = {0, 0};
336	    unsigned long start_time;
337	    unsigned int cost_time = 0;
338	
339	    if (handle == (mmProcess)EN_ERROR) {
340	        HDC_LOG_ERR("Input parameter handle is invalid.\n");
341	        return DRV_ERROR_INVALID_HANDLE;
342	    }
343	
344	    hdcCmd.send.session = pSession->sockfd;
345	    hdcCmd.send.src_buf = pMsg->bufList[0].pBuf;
346	    hdcCmd.send.len = pMsg->bufList[0].len;
347	    hdcCmd.send.wait_flag = wait;
348	    hdcCmd.send.timeout = timeout;
349	    hdcCmd.send.dev_id = (int)pSession->device_id;
350	
351	    if (wait == HDC_WAIT_TIMEOUT) {
352	        (void)clock_gettime(CLOCK_MONOTONIC, &now_time);
353	        start_time = (unsigned long)((now_time.tv_sec * CONVERT_MS_TO_S) + (now_time.tv_nsec / CONVERT_MS_TO_NS));
354	    }
355	
356	retry:
357	    ret = hdc_ioctl(handle, HDCDRV_SEND, &hdcCmd);
358	
359	    if (ret == ERESTARTSYS) {
360	        if (wait == HDC_WAIT_TIMEOUT) {
361	            (void)clock_gettime(CLOCK_MONOTONIC, &now_time);
362	            cost_time = (unsigned int)((unsigned long)((now_time.tv_sec * CONVERT_MS_TO_S) +
363	                                                       (now_time.tv_nsec / CONVERT_MS_TO_NS)) -
364	                                       start_time);
365	            if (cost_time < timeout) {
366	                hdcCmd.send.timeout = timeout - cost_time;
367	                goto retry;
368	            } else {
369	                return -HDCDRV_TX_TIMEOUT;
370	            }
371	        } else {
372	            goto retry;
373	        }
374	    }
375	
376	    return ret;
377	}
