                hdcCmd.recv_peek.timeout = recvConfig->timeout - (unsigned int)cost_time;
                goto retry;
            } else {
                return -HDCDRV_RX_TIMEOUT;
            }
        } else {
            goto retry;
        }
    }

    return ret;
}

